INSERT INTO public.course_offering_meeting (course_offering_group_id, weekday, starts_at, ends_at, classroom, room_id)
SELECT g.id, s.weekday, s.starts_at, s.ends_at, s.classroom, r.id
FROM src s
JOIN public.course c ON c.code=s.offering_course
JOIN public.campus cp ON cp.code=s.campus_code
JOIN public.academic_term at ON at.external_key=s.term_key
JOIN public.course_offering co ON co.course_id=c.id AND co.campus_id=cp.id AND co.academic_term_id=at.id
JOIN public.course_offering_group g ON g.course_offering_id=co.id AND g.group_code=s.group_code
LEFT JOIN public.room r ON r.campus_id=cp.id AND r.building=s.building AND r.number=s.number
ON CONFLICT (course_offering_group_id, weekday, starts_at, ends_at) DO UPDATE SET classroom=EXCLUDED.classroom, room_id=EXCLUDED.room_id, is_active=TRUE, deactivated_at=NULL, updated_at=NOW();

